mapper.select:
SELECT id, at, actor_type, actor_id, actor_label, service, method, path, status, duration_ms
  FROM audit_log
 WHERE org_id = #{orgId}
AND service = #{service}
AND actor_type = #{actorType}
AND at >= #{from}
AND at < #{to}
AND UPPER(path) LIKE #{like} ESCAPE '!'
AND (at < #{cursorAt} OR (at = #{cursorAt} AND id < #{cursorId}))
 ORDER BY at DESC, id DESC LIMIT #{limit}
